begin;
create temp table lf(u uuid,v uuid,a uuid,t uuid,held uuid,j uuid,i uuid,q uuid,p uuid);
insert into lf values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),null);
grant select,update on lf to authenticated;
insert into auth.users(id,email) select u,'learning-'||u::text||'@example.invalid' from lf union all select v,'learning-'||v::text||'@example.invalid' from lf;
insert into accounts(id,user_id,name,type,currency) select a,u,'Policy fixture','credit','USD' from lf;
insert into transactions(id,user_id,account_id,name,merchant_name,date,amount,category,classification_source,needs_review)
select t,u,a,'ACME insurance #456','ACME insurance #456',date '2090-01-01',500,'Other','auto',true from lf union all select held,u,a,'Held purchase','Held purchase',date '2090-01-02',15,'Other','auto',true from lf;
create temp table lf_ledger as select count(*) n,sum(amount) total from transactions;
create function pg_temp.lf_snapshot(_id uuid) returns jsonb language sql as $$select jsonb_build_object('id',t.id,'updated_at',t.updated_at,'amount',t.amount,'date',t.date,'account_id',t.account_id,'category',t.category) from transactions t where id=_id$$;
insert into finance_ai_policies(owner_id,module,mode,tasks,auto_tasks) select u,'transactions','ai',array['categories','receipts'],array['categories','receipts'] from lf;
insert into finance_assistant_jobs(id,owner_id,module,task,policy_revision,context_cipher,snapshot) select j,u,'transactions','categories',1,'synthetic',jsonb_build_object('learning_revision',0,'transactions',jsonb_build_object(t::text,pg_temp.lf_snapshot(t),held::text,pg_temp.lf_snapshot(held))) from lf;
insert into finance_assistant_items(id,owner_id,job_id,module,task,fingerprint,kind,payload,status) select i,u,j,'transactions','categories',i::text,'category',jsonb_build_object('transaction_id',t,'category','Bills & Utilities'),'ready' from lf union all select q,u,j,'transactions','categories',q::text,'question',jsonb_build_object('transaction_id',t,'question','What are the coverage dates?'),'needs_input' from lf;
insert into finance_documents(owner_id,kind,name,payload) select u,'close','Held fixture',jsonb_build_object('reviewScope',jsonb_build_object('version',1,'ownerId',u,'accountIds',jsonb_build_array(a),'start','2090-01-02','end','2090-01-02')) from lf;
set local role authenticated;
do $$declare f record;r jsonb;blocked boolean;begin
 select * into f from lf;perform set_config('request.jwt.claim.sub',f.u::text,true);
 r:=finance_save_learning_policy(null,0,jsonb_build_object('title','Coverage','guidance','Spread confirmed coverage.','effect','spread_service','module','all','merchant','acme insurance','currency','USD','min_amount',0,'max_amount',500,'starts_on','2090-01-01','ends_on','2090-12-31','enabled',true));update lf set p=(r->>'id')::uuid;
 blocked:=false;begin perform finance_assistant_apply(f.i,1,true);exception when raise_exception then if sqlerrm not like 'Your policies changed%' then raise;end if;blocked:=true;end;if not blocked then raise exception 'Stale policy generation applied';end if;
 blocked:=false;begin perform finance_save_learning_policy((r->>'id')::uuid,0,r);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Stale edit accepted';end if;
 blocked:=false;begin update finance_learning_policies set enabled=false;exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Direct policy write accepted';end if;
 blocked:=false;begin perform finance_assistant_apply_before_learning(f.i,1,true);exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Policy checks bypassed';end if;
 blocked:=false;begin perform finance_ai_apply_receipts(jsonb_build_array(jsonb_build_object('category','Bills & Utilities','expected',pg_temp.lf_snapshot(f.t))));exception when raise_exception then if sqlerrm not like 'Your policy requires%' then raise;end if;blocked:=true;end;if not blocked then raise exception 'Receipt approval bypassed timing';end if;
 r:=finance_assistant_update(f.q,1,'answer','{"answer":"Coverage is 2090-01-01 through 2090-12-31."}');
 perform finance_assistant_update(f.q,2,'done','{}');
 r:=finance_assistant_update(f.q,3,'answer','{"answer":"Correction: coverage ends 2090-11-30."}');
 if r->>'status'<>'needs_input' or r->>'revision'<>'4' then raise exception 'Answer correction not queued';end if;
 if (select count(*) from finance_assistant_history where item_id=f.q)<>3 then raise exception 'Answer history missing';end if;
 if (select count(*) from finance_learning_policies)<>1 then raise exception 'Answer silently created policy';end if;
 perform set_config('request.jwt.claim.sub',f.v::text,true);
 if exists(select 1 from finance_learning_policies) or exists(select 1 from finance_learning_history) then raise exception 'Another user read policies';end if;
 blocked:=false;begin perform finance_save_learning_policy((select p from lf),1,r);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Another user changed policy';end if;
end;$$;
reset role;
do $$declare f record;begin select * into f from lf;
 if (select count(*) from finance_matching_policies(f.u,f.t,'transactions'))<>1 then raise exception 'SQL scope does not match evaluator';end if;
 update transactions set date='2089-12-31' where id=f.t;
 if exists(select 1 from finance_matching_policies(f.u,f.t,'transactions')) then raise exception 'Date boundary escaped';end if;
 update transactions set date='2090-01-01',merchant_name='notacme insurance' where id=f.t;
 if exists(select 1 from finance_matching_policies(f.u,f.t,'transactions')) then raise exception 'Merchant phrase boundary escaped';end if;
 update transactions set merchant_name='ACME insurance #456' where id=f.t;
 update finance_assistant_jobs set snapshot=snapshot||jsonb_build_object('learning_revision',1,'transactions',jsonb_build_object(f.t::text,pg_temp.lf_snapshot(f.t),f.held::text,pg_temp.lf_snapshot(f.held))) where id=f.j;
end;$$;
set local role authenticated;
do $$declare f record;blocked boolean;begin select * into f from lf;perform set_config('request.jwt.claim.sub',f.u::text,true);
 blocked:=false;begin perform finance_assistant_apply(f.i,1,true);exception when raise_exception then if sqlerrm not like 'Your policy requires%' then raise;end if;blocked:=true;end;if not blocked then raise exception 'Automatic category escaped policy';end if;
 perform finance_assistant_apply(f.i,1,false);
 perform finance_assistant_apply(f.i,1,false); -- Idempotent explicit override.
end;$$;
reset role;
do $$declare f record;begin select * into f from lf;
 insert into finance_assistant_items(owner_id,job_id,module,task,fingerprint,kind,payload,status) values(f.u,f.j,'transactions','categories','held','category',jsonb_build_object('transaction_id',f.held,'category','Food & Dining'),'ready');
 update finance_assistant_jobs set snapshot=snapshot||jsonb_build_object('answer_values',jsonb_build_object(f.q::text,'old answer')) where id=f.j;
end;$$;
set local role authenticated;
do $$declare f record;k uuid;blocked boolean;begin select * into f from lf;perform set_config('request.jwt.claim.sub',f.u::text,true);select id into k from finance_assistant_items where fingerprint='held';
 blocked:=false;begin perform finance_assistant_apply(k,1,false);exception when raise_exception then if sqlerrm not like 'Your saved answers changed%' then raise;end if;blocked:=true;end;if not blocked then raise exception 'Changed facts applied';end if;
end;$$;
reset role;
update finance_assistant_jobs set snapshot=snapshot-'answer_values' where id=(select j from lf);
set local role authenticated;
do $$declare f record;k uuid;blocked boolean;begin select * into f from lf;perform set_config('request.jwt.claim.sub',f.u::text,true);select id into k from finance_assistant_items where fingerprint='held';
 blocked:=false;begin perform finance_assistant_apply(k,1,false);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Closed transaction changed';end if;
end;$$;
reset role;
do $$begin if exists(select 1 from lf_ledger where n<>(select count(*) from transactions) or total is distinct from (select sum(amount) from transactions)) then raise exception 'Policies changed financial amounts';end if;end;$$;
rollback;
select 'PASS policy isolation, stale revisions, automatic guards, explicit override, idempotence, saved answers, audit trail, date/merchant matching, closed periods and unchanged amounts; fixtures rolled back.' as result;
